begin;
set local standard_conforming_strings = on;
insert into public.knowledge_articles
    (id, title, content, source_title, source_url, keywords, active)
values
('20000000-0000-4000-8000-000000000001', 'Как оформить отпуск', 'На главной странице PostTech нажмите «Оформить отпуск». В календаре выберите даты начала и окончания, нажмите «Продолжить», проверьте заявку и нажмите «Отправить заявку». Комментарий необязателен: добавьте его при необходимости. Сумма для отпуска не указывается.

Начало отпуска — сегодня или позже; окончание не раньше начала. Портал считает календарные дни включительно, в том числе выходные, проверяет доступный остаток и пересечение с вашими ожидающими или одобренными отпусками. После отправки дни резервируются, заявка получает статус «На согласовании». Согласующие показаны перед отправкой. Правила компании о сроке подачи, ежегодной норме дней и учёте праздничных дней в этой базе не утверждены; уточните их у HR.', 'Демо: оформление заявки на отпуск', null, array['отпуск', 'заявка', 'оформить', 'даты', 'демалыс']::text[], true),
('20000000-0000-4000-8000-000000000002', 'Как запросить аванс', 'На главной странице PostTech нажмите «Запросить аванс» или создайте в разделе «Заявки» заявку типа «Аванс». Укажите положительную сумму в тенге, при необходимости добавьте необязательный комментарий, проверьте заявку и отправьте её. Даты отпуска для аванса не заполняются.

Заявка направляется назначенному руководителю сотрудника или HR по показанному маршруту; автор не согласует собственную заявку. Решение и комментарий согласующего, если он указан, доступны в карточке заявки. Одобрение не выполняет банковский перевод. База не устанавливает график выплат, долю зарплаты для аванса и срок перечисления — их уточняют в HR.', 'Демо: оформление заявки на аванс', null, array['аванс', 'запросить', 'сумма', 'заявка', 'тенге']::text[], true),
('20000000-0000-4000-8000-000000000003', 'Кто видит кадровые данные', 'Сотрудник видит свой профиль и свои заявки. Руководитель и директор видят профили и обучение только своих прямых подчинённых. HR-администратор видит профили и заявки всех сотрудников. Личные уведомления доступны только их получателю.

Доступ руководителя или директора к чужой заявке определяется назначенным при отправке маршрутом согласования, ранее принятым им решением либо действующим замещением для ожидающей заявки. Смена руководителя не передаёт новому руководителю старые заявки автоматически. Замещение не открывает чужие профили и обучение всей команды. Автор не может согласовать свою заявку.

Роль назначает HR, сервер проверяет её при каждом запросе. Текст в чате не расширяет права. Обычные ответы AI Jana используют общую базу знаний и не раскрывают персональные сведения работников. Отдельная «Моя сводка» формируется сервером только по доступным пользователю данным; эти записи не отправляются модели.', 'Демо: роли и доступ к данным', null, array['доступ', 'роль', 'кадровые', 'данные', 'руководитель', 'директор', 'видит']::text[], true),
('20000000-0000-4000-8000-000000000004', 'Где посмотреть статус и комментарий к заявке', 'Откройте «Мои заявки» и нужную карточку. «На согласовании» (pending) означает ожидание решения; «Согласовано» (approved) — положительное решение; «Отклонено» (rejected) — отказ; «Отозвана» (cancelled) — автор отозвал заявку до решения. В карточке есть маршрут и история согласования, а комментарий руководителя или HR отображается, если он указан. При отклонении причина обязательна.

Статус согласования и оформление HR — разные этапы: согласованная заявка ещё может ожидать оформления документа. Изменения заявки и личные уведомления обновляются в открытом портале без ручной перезагрузки при доступном соединении. Текущий статус конкретной заявки смотрите в её карточке; общий ответ AI Jana не проверяет персональную заявку. Обязательный срок рассмотрения этой базой не установлен.', 'Демо: статусы заявок', null, array['статус', 'заявки', 'комментарий', 'pending', 'approved', 'rejected', 'cancelled']::text[], true),
('20000000-0000-4000-8000-000000000005', 'Где посмотреть остаток и резерв отпуска', 'Доступные дни отпуска показаны на главной странице, в профиле и при оформлении отпуска. В подробном расчёте различаются «Кадровый остаток», «На согласовании», «Одобрено, до сверки» и «Доступно для новой заявки».

Доступный остаток равен кадровому остатку за вычетом резервов ожидающих и одобренных, ещё не сверенных заявок. При отправке отпуска дни резервируются сразу. После согласования этот же резерв сохраняется до сверки HR; повторного списания нет. При отклонении или отзыве ожидающей заявки резерв освобождается один раз, доступные дни возвращаются, а кадровый остаток не изменяется.

Кадровый остаток не списывается автоматически: HR обновляет его по подтверждённым данным и снимает уже учтённые резервы при сверке. Если видите ошибку, обратитесь в HR. AI Jana не сообщает персональное число дней из профиля и не определяет ежегодную норму отпуска.', 'Демо: остаток отпускных дней', null, array['остаток', 'резерв', 'отпускных', 'дней', 'баланс', 'профиль']::text[], true),
('20000000-0000-4000-8000-000000000006', 'Как исправить сведения или телефон в профиле', 'Сведения в «Моём профиле», включая телефон, имя, должность, подразделение, руководителя и кадровый остаток отпуска, доступны сотруднику только для чтения. Самостоятельно изменить телефон или официальные кадровые данные в профиле нельзя. Для исправления обратитесь в HR и укажите, какое поле требует изменения; AI Jana профиль не редактирует.

Для обращения откройте «Помощь» и передайте вопрос в HR, проверьте текст и подтвердите отправку. Не публикуйте чужие персональные данные в чате. После регистрации по действующему приглашению и подтверждения почты портал создаёт профиль с назначенными HR данными и ролью. Если профиль не появился или доступ запрещён, обратитесь к HR или администратору.', 'Демо: кадровый профиль', null, array['профиль', 'телефон', 'исправить', 'изменить', 'должность', 'регистрация']::text[], true),
('20000000-0000-4000-8000-000000000007', 'Моё обучение: назначенные, внешние и личные курсы', 'Откройте раздел «Обучение» (Jana Academy): в «Моём обучении» видны ваши курсы, прогресс, результат и срок прохождения, если он задан. На главной странице можно продолжить курс кнопкой «Продолжить». Наличие курса в каталоге само по себе не означает, что он вам назначен.

Курсы назначает HR, а руководитель или директор — своим прямым подчинённым. Назначение создаёт уведомление сотруднику. Для внутреннего курса с уроками и тестом нужно назначение; если его нет, обратитесь к руководителю или HR. Внешний курс из каталога сотрудник может открыть и нажать «Добавить в моё обучение» без назначения HR. AI Jana показывает переход к обучению, но не назначает курсы и не меняет результаты.

Если внешнего курса нет в каталоге, откройте «Обучение» → «Свой курс». Укажите название, площадку (например, Яндекс Практикум), ссылку https:// без логина и пароля, обязательный срок «Пройти до» и текущий целый процент от 0 до 100. Нажмите «Добавить курс». При 100% подтвердите «Я завершил курс на площадке». Курс появится в «Моём обучении»; в общий каталог он не добавляется. Руководитель или директор видит личные курсы прямых подчинённых, HR — всех сотрудников. Сроки показаны в личном календаре и календаре команды в пределах этих прав.

Внешнее обучение проходит на площадке по кнопке «Открыть на площадке». В PostTech сотрудник сам указывает «Пройдено, %» и нажимает «Сохранить прогресс». Процент — целое число от 0 до 100; ранее сохранённый прогресс уменьшить нельзя. Для 100% подтвердите «Я завершил курс на площадке»: курс станет завершённым без внутреннего теста и проходного балла. Это самоотчёт сотрудника, а не проверенный сертификат или автоматическая синхронизация с площадкой. Руководитель и HR видят обновлённый прогресс в обучении.', 'Демо: обучение и личные внешние курсы PostTech', null, array['обучение', 'назначение', 'курс', 'курсы', 'academy', 'личный', 'свой', 'внешний', 'ссылка', 'площадка', 'прогресс', 'процент', 'календарь', 'яндекс']::text[], true),
('20000000-0000-4000-8000-000000000008', 'Как пройти внутренний курс с уроками и тестом', 'Для внутреннего курса откройте «Обучение», выберите назначенный курс и изучите материал. Если курс разбит на уроки, завершите каждый кнопкой «Завершить урок»; все уроки должны быть завершены до теста. Для курса без отдельных уроков подтвердите изучение материала перед переходом к тесту.

Ответьте на все вопросы теста и нажмите «Завершить тест». Сервер рассчитывает результат. Курс получает статус «Завершено» и прогресс 100% только при достижении проходного балла, показанного в карточке именно этого курса. Порог настраивается для каждого курса; значение по умолчанию — 80%.

Если баллов не хватило, курс остаётся в процессе, попытка сохраняется и тест можно повторить. Результат и история попыток доступны в карточке курса. При успешном завершении уведомления получают сотрудник и его назначенный руководитель.

Для внешнего курса эти правила тестирования не применяются: сотрудник проходит обучение на внешней площадке и сам сохраняет прогресс в PostTech. При 100% после подтверждения завершения курс получает статус «Завершено» без внутреннего теста. Самоотчёт не является проверкой сертификата площадки.', 'Демо: прохождение курса и тест', null, array['курс', 'прогресс', 'тест', 'результат', 'обучение', 'урок', 'завершить']::text[], true),
('20000000-0000-4000-8000-000000000009', 'Где читать уведомления и как они обновляются', 'Откройте колокольчик или раздел «Уведомления». Здесь появляются изменения статуса ваших заявок, назначения и успешное завершение курсов, ответы HR на обращения. Назначенный согласующий получает уведомление о новой заявке. При отзыве ожидающей заявки уведомления получают автор, назначенные согласующие и действующие заместители; согласование больше не требуется.

Уведомление можно отметить прочитанным и открыть связанный объект. Списки, счётчики и статусы в открытой вкладке обновляются без ручной перезагрузки при доступном соединении; после возвращения во вкладку данные проверяются снова. Пользователь видит только свои уведомления, включая HR. Это уведомления внутри портала: наличие почтовой отправки приглашений не означает, что все события дублируются по email или SMS.', 'Демо: центр уведомлений', null, array['уведомления', 'колокольчик', 'прочитанным', 'обновление', 'статус']::text[], true),
('20000000-0000-4000-8000-000000000010', 'Что умеет AI Jana и как передать вопрос в HR', 'AI Jana объясняет работу PostTech по опубликованной базе знаний, показывает источники и предлагает переходы к нужным разделам. Каждый вопрос обрабатывается отдельно: для уточнения повторите нужный контекст. Общий ответ не раскрывает персональные записи сотрудников, не одобряет и не отзывает заявки, не меняет профили, роли и результаты курсов. Кнопка перехода открывает форму или раздел; отправку заявки подтверждает пользователь.

Если ответа в базе нет, не следует придумывать кадровое правило. Нажмите «Передать вопрос в HR», проверьте вопрос и контекст, отметьте согласие на передачу и нажмите «Отправить в HR». Обращение создаётся только после этого подтверждения; вся история чата автоматически не передаётся. Ответ HR появится в обращении и уведомлениях. Адрес, телефон HR и обязательный срок ответа этой базой не заданы.

Jana не отвечает на посторонние темы вне портала и кадровых процессов. Пароли, токены и ключи в чат передавать нельзя. Отдельная «Моя сводка» показывает доступные пользователю задачи портала и формируется сервером без передачи этих записей языковой модели.', 'Демо: границы AI Jana и обращения в HR', null, array['jana', 'ассистент', 'помощь', 'источники', 'hr', 'обращение']::text[], true),
('20000000-0000-4000-8000-000000000011', 'Как перенести отпуск в Google Calendar', 'Для одобренного отпуска скачайте файл .ics в карточке заявки. В разделе «Календарь» можно экспортировать разрешённые вам согласованные отпуска выбранного периода. На компьютере откройте Google Calendar → Настройки → Импорт и экспорт, выберите скачанный файл и целевой календарь, затем нажмите «Импортировать». Последний день отпуска включён.

Это ручной перенос, без автоматической синхронизации и без подключения аккаунта Google к PostTech. Изменения в портале не обновляют импортированные события; исправляйте их в Google Calendar вручную. Повторный импорт может создать дубликаты. В файл попадают только одобренные отпуска в пределах ваших прав; если таких отпусков нет, файл будет пустым. Курсы и несогласованные отпуска этим экспортом не переносятся.', 'Демо: экспорт отпуска в календарь', null, array['календарь', 'google', 'ics', 'отпуск', 'импорт', 'синхронизация']::text[], true),
('20000000-0000-4000-8000-000000000012', 'Как отозвать отпуск и вернуть зарезервированные дни', 'Автор может отозвать только свою заявку со статусом «На согласовании» (pending). Откройте «Мои заявки», выберите отпуск, нажмите «Отозвать заявку» и подтвердите отзыв. Статус станет «Отозвана», действие сохранится в истории, согласующие получат уведомление. Возобновить эту заявку нельзя; при необходимости создайте новую.

При отзыве или отклонении ожидающей заявки её резерв дней освобождается один раз. Доступный остаток увеличивается на освобождённые дни, а кадровый остаток не меняется. Повторный отзыв уже отозванной заявки не начисляет дни повторно. Списки, баланс и уведомления обновляются в открытом портале без ручной перезагрузки при доступном соединении.

Уже согласованный отпуск самостоятельно отменить этой кнопкой нельзя. Для изменения согласованного отпуска обратитесь в HR; автоматический возврат дней для такой отмены в портале не предусмотрен.', 'Демо: отзыв и отклонение отпуска', null, array['отпуск', 'отозвать', 'отмена', 'отклонение', 'возврат', 'дни', 'резерв']::text[], true),
('20000000-0000-4000-8000-000000000013', 'Что делать, если тест курса не сдан', 'Если результат ниже проходного балла этого курса, курс остаётся в процессе, а результат попытки сохраняется. В карточке курса выберите «Повторить материал» или «Повторить тест», ответьте на все вопросы и снова нажмите «Завершить тест». История попыток показывает результат каждой отправки.

Проходной балл указан в карточке курса и настраивается отдельно; по умолчанию это 80%. Текущий портал не задаёт ограничения на число неуспешных попыток или обязательную паузу между ними. Все уроки и материал должны быть завершены до теста. После успешной сдачи курс завершён; повторная отправка не перезаписывает успешный результат. Если тест недоступен или материал не открывается, обратитесь к HR.', 'Демо: повторная попытка обучения', null, array['курс', 'тест', 'не сдал', 'пересдача', 'попытки', 'повторить', 'балл']::text[], true),
('20000000-0000-4000-8000-000000000014', 'Кто согласует отпуск руководителя, директора или HR', 'Любая роль, включая руководителя, директора и HR, оформляет собственный отпуск в личном кабинете обычным способом. Автор никогда не согласует свою заявку. Если в профиле указан допустимый вышестоящий руководитель, директор или HR и нет ошибки в цепочке подчинения, заявка направляется этому человеку. Само название роли «директор» не делает её автоматическим согласующим для всех.

Если допустимый руководитель не настроен, заявка направляется другим HR-администраторам, исключая автора. Если нет ни допустимого руководителя, ни другого HR, отправка заблокирована: HR должен исправить маршрут. Согласующие показаны перед отправкой и сохраняются в заявке; смена руководителя в профиле не меняет уже отправленный маршрут автоматически. На время отсутствия может действовать оформленное HR замещение.', 'Демо: маршрут согласования', null, array['руководитель', 'директор', 'hr', 'свой отпуск', 'согласование', 'маршрут']::text[], true),
('20000000-0000-4000-8000-000000000015', 'Как получить доступ и назначенную HR роль', 'Доступ в рабочий портал выдаёт HR: создаёт приглашение на конкретный email, назначает роль и данные сотрудника, включая руководителя. При настроенной почтовой отправке приходит письмо с кодом приглашения и назначенной ролью. Если письмо не отправлено или приглашение истекло, HR проверяет отправку и выдаёт новый код.

На экране входа нажмите «Активировать приглашение», введите код из письма, заполните данные аккаунта и создайте пароль. Подтвердите адрес кодом из письма подтверждения, если портал запросит этот шаг. Код приглашения и код подтверждения email — разные коды. После успешной активации создаётся кадровый профиль с ролью, назначенной HR.

В рабочем режиме пользователь не выбирает роль сам и не повышает права через чат. Выбор роли на экране демонстрации относится только к демо. Для изменения роли или ошибки в приглашении обратитесь в HR.', 'Демо: регистрация по приглашению', null, array['регистрация', 'приглашение', 'код', 'роль', 'почта', 'доступ']::text[], true),
('20000000-0000-4000-8000-000000000016', 'Как руководителю согласовать или отклонить заявку', 'Руководитель, директор или HR открывает раздел «На согласование», выбирает доступную ожидающую заявку и проверяет её данные. Для положительного решения нажмите «Согласовать заявку» и подтвердите его. Для отказа выберите отклонение, обязательно укажите причину и подтвердите решение. При согласовании комментарий необязателен.

Решение допускается только для заявки со статусом «На согласовании», в пределах назначенного маршрута или действующего замещения. HR может рассматривать доступные ему чужие заявки. Самосогласование запрещено для всех ролей. После решения сотрудник получает уведомление; повторное конкурирующее решение не заменяет уже принятое.

Замещение оформляет HR на определённые даты. Оно позволяет заместителю рассматривать ожидающие заявки назначенного согласующего, но не даёт доступ ко всем профилям и обучению его команды. История заявки сохраняет автора решения и сведения о замещении.', 'Демо: решение согласующего и замещение', null, array['согласовать', 'отклонить', 'причина', 'руководитель', 'директор', 'замещение']::text[], true),
('20000000-0000-4000-8000-000000000017', 'Что происходит после согласования и как оформляет HR', '«Согласовано» означает, что решение по заявке принято, но оформление HR — отдельный этап. В карточке заявки можно увидеть состояние оформления: ожидает HR, в работе или оформлено. HR фиксирует документ и основание завершения; само согласование не выполняет банковскую выплату и не подтверждает появление документа во внешней системе.

Для 1С и Documentolog предусмотрена очередь событий с повторными попытками доставки и защитой от дублирования. Автоматическая отправка требует настроенных приёмников; если они не подключены, HR оформляет документ вручную. Статус доставки проверяется отдельно, ожидание в очереди не означает успешную доставку.

При отпуске резерв одобренной заявки сохраняется до сверки кадрового остатка HR. Оформление документа само по себе не должно повторно списывать дни. Утверждённые сроки оформления, выплаты аванса и отпускных в этой базе не установлены.', 'Демо: оформление HR и интеграции', null, array['согласовано', 'оформление', 'hr', 'документ', '1с', 'documentolog', 'интеграция']::text[], true),
('20000000-0000-4000-8000-000000000018', 'Что делать, если отпуск пересекается с существующей заявкой', 'Портал не разрешает создать отпуск, пересекающийся с вашей действующей заявкой в статусе «На согласовании» или «Согласовано». При выборе дат показано сообщение о пересечении и ссылка на существующую заявку. Откройте её и проверьте даты и статус вместо повторной отправки.

Можно выбрать непересекающийся период. Если старая заявка ещё на согласовании и больше не нужна, её автор может отозвать её и затем оформить новую; резерв старой заявки освободится один раз. Уже согласованный отпуск самостоятельно отозвать нельзя — для изменения обратитесь в HR. Отклонённые и отозванные заявки не блокируют новый период.

Период должен начинаться сегодня или позже, дата окончания не раньше начала, а календарных дней должно хватать в доступном остатке с учётом остальных резервов.', 'Демо: проверка периода отпуска', null, array['отпуск', 'пересечение', 'существующая заявка', 'даты', 'конфликт', 'дубликат']::text[], true)
